select throws_ok($$select pg_temp.enqueue(configs=>'[{"maximum": "6", "lead_time": 0, "review_interval": 1, "moq": "0", "pack": "0.0001"}]')$$,'MQ422',null,'invalid pack 0.0001 rejected');
