select throws_ok($$select pg_temp.enqueue(source=>999)$$,'MQ404',null,'missing source unavailable');
reset role;
update public.locations set is_active=false where id=pg_temp.id(20);
set local role authenticated;
select throws_ok($$select pg_temp.enqueue()$$,'MQ422',null,'inactive location blocked');
reset role;
update public.locations set is_active=true where id=pg_temp.id(20);
set local role authenticated;
insert into saved(run) values(pg_temp.enqueue());
select is(pg_temp.enqueue(configs=>'[{"maximum":"06.000","lead_time":365,"review_interval":365,"moq":"0","pack":"0.001"},{"maximum":"6","lead_time":1,"review_interval":2,"moq":"0","pack":"0.001"},{"maximum":"06","lead_time":0,"review_interval":1,"moq":"0","pack":"0.001"}]'),(select run from saved),'canonical order-independent retry');
select throws_ok($$select pg_temp.enqueue(configs=>'[{"maximum":"6","lead_time":2,"review_interval":2,"moq":"0","pack":"0.001"}]')$$,'MQ409',null,'different settings conflict');
select throws_ok($$select pg_temp.enqueue(request=>71)$$,'MQ409',null,'one active run per organization');
select throws_ok($$select * from planning.simulation_inputs$$,'42501',null,'browser cannot read staging');
select throws_ok($$update public.policy_simulations set unit='KG'$$,'42501',null,'results immutable');
reset role;
update saved set payload=i.payload from planning.simulation_inputs i where i.run_id=saved.run;
select is((select payload#>'{source_simulation,evidence}' from saved),(select evidence from public.policy_simulations where run_id=pg_temp.id(60)),'full source copied');
select ok(app.simulation_output_valid((select payload from saved),(select output from expected)),'configured timing and exact ledgers accepted');
select ok(not app.simulation_output_valid((select payload from saved),'{}'),'malformed output rejected');
select ok(not app.simulation_output_valid((select payload from saved),jsonb_set((select output from expected),'{variants,0,lead_time}','2')),'tampered variants,0,lead_time rejected');
select ok(not app.simulation_output_valid((select payload from saved),jsonb_set((select output from expected),'{variants,3,review_interval}','1')),'tampered variants,3,review_interval rejected');
select ok(not app.simulation_output_valid((select payload from saved),jsonb_set((select output from expected),'{variants,3,ledger,0,order_due}','"2026-01-03"')),'tampered variants,3,ledger,0,order_due rejected');
select ok(not app.simulation_output_valid((select payload from saved),jsonb_set((select output from expected),'{variants,3,metrics,ending_on_order}','"0"')),'tampered variants,3,metrics,ending_on_order rejected');
select ok(not app.simulation_output_valid((select payload from saved),jsonb_set((select output from expected),'{variants,0,metrics,days}','99')),'tampered variants,0,metrics,days rejected');
update public.planning_runs set status='running' where id=(select run from saved);
update planning.leases set token=pg_temp.id(80),expires_at=clock_timestamp()+interval '1 minute' where run_id=(select run from saved);
create temporary table published(value boolean);
grant insert on published to maqdar_worker;
set local role maqdar_worker;
insert into published select app.simulation_finish((select run from saved),pg_temp.id(80),(select output from expected));
reset role;
select ok((select value from published),'existing worker capability publishes constraints');
select is((select count(*)::integer from planning.simulation_inputs where run_id=(select run from saved)),0,'staging cleaned');
select is((select result->>'method' from public.planning_runs where id=(select run from saved)),'periodic-constraints-v1','method retained');
select pg_temp.login(11);
set local role authenticated;
select is((select count(*)::integer from public.policy_simulations),2,'viewer reads results');
select pg_temp.login(12);
select is((select count(*)::integer from public.policy_simulations),0,'unassigned branch sees no results');
reset role;
insert into public.membership_locations values(pg_temp.id(1),pg_temp.id(12),pg_temp.id(20));
set local role authenticated;
select is((select count(*)::integer from public.policy_simulations),2,'assigned branch reads results');
select pg_temp.login(13,2);
select is((select count(*)::integer from public.policy_simulations),0,'foreign organization sees no results');
reset role;
delete from public.planning_runs where id=pg_temp.id(60);
select pg_temp.login(10);
set local role authenticated;
select is(pg_temp.enqueue(),(select run from saved),'terminal retry survives source deletion');
reset role;
select ok(not has_function_privilege('service_role','public.simulation_constraints_enqueue(uuid,uuid,uuid,jsonb,boolean)','EXECUTE'),'API role gains no capability');
select ok(not has_function_privilege('maqdar_worker','app.simulation_constraints_canonical(jsonb)','EXECUTE'),'canonical helper private');
select ok(not has_function_privilege('maqdar_worker','app.simulation_output_valid_configurations_v1(jsonb,jsonb)','EXECUTE'),'prior validator private');
select is((select count(*)::integer from public.stock_snapshots where organization_id=pg_temp.id(1)),0,'no stock created');
select is((select count(*)::integer from public.open_orders where organization_id=pg_temp.id(1)),0,'no order created');
select ok(not has_function_privilege('authenticated','app.simulation_constraints_ledger_valid(jsonb,jsonb,jsonb)','EXECUTE'),'exact ledger validator private');
select * from finish();
rollback;
